<div class="page-head"><div><h2><?=e($role)?> Dashboard</h2><p>Akufada Microfinance Institution • Head Office</p></div></div>
<?php if(in_array($role,['Admin','HR Admin','Supervisor'],true)):?><div class="grid stats"><?php foreach($counts as $c):?><div class="card stat"><div><span class="muted"><?=e($c[0])?></span><strong><?=e((string)$c[1])?></strong></div><div class="symbol">▣</div></div><?php endforeach;?></div><?php endif;?>
<div class="card"><h3><?=e($role)?> Quick Actions</h3><div class="quick"><?php foreach($links as $l):?><a class="quick-card" href="<?=e(APP_URL.'/'.$l[1])?>"><b><?=e($l[0])?></b><small>Open <?=e(strtolower($l[0]))?></small></a><?php endforeach;?></div></div>
<?php if(in_array($role,['Admin','HR Admin'],true)):?><div class="card"><h3>Recent employees</h3><div class="table-wrap"><table><tr><th>Employee ID</th><th>Name</th><th>Department</th><th>Branch</th><th>Status</th></tr><?php foreach($pdo->query('SELECT employee_code,full_name,department,branch,status FROM employees ORDER BY id DESC LIMIT 10') as $r):?><tr><td><?=e($r['employee_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['branch'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div><?php endif;?>
